window.STATION_PARTS=window.STATION_PARTS||{};
window.STATION_PARTS["fuego"]={"id":"fuego","title":"Fire protection","color":"#55687A","stations":[
{"id":"fir-1","subject":"fuego","order":1,"kind":"lesson","level":1,"ident":"FIR","title":"Fire protection at a glance","goal":"Explicar qué zonas del avión tienen detección de fuego o de humo, cuáles tienen extinción y cuáles se extinguen solas.","intro":"Empezamos por el mapa: dónde se detecta fuego, dónde humo, y dónde hay con qué apagarlo.","minutes":4,"cards":[{"id":"fir-1-c1","title":"Detect and extinguish","body":"La protección contra fuego y humo tiene tres partes:\n- **detección de fuego y sobretemperatura** en los **motores** y el **APU**;\n- **detección de humo** en las **bodegas de carga**, los **lavatorios** y la **aviónica**;\n- **extinción** en las bodegas de carga, los motores, el APU y los lavatorios.\n\nAdemás hay **extintores portátiles** en la cabina de mando y en la cabina de pasajeros.","diagram":{"alt":"Tabla de la protección contra fuego. Motores: detección de fuego y dos botellas por motor, descarga manual. APU: detección de fuego y una botella, descarga automática en tierra. Bodegas: detección de humo y descarga manual. Lavatorios: detección de humo y extinción automática en el wastebin. Aviónica: solo detección de humo.","src":"assets/estaciones/diagramas/fir-mapa.svg"},"keyIdea":"Fuego en motores y APU; humo en bodegas, lavatorios y aviónica; extinción en todo salvo la aviónica."},{"id":"fir-1-c2","title":"What extinguishes by itself","body":"La extinción **automática** es la excepción. Solo la tienen:\n- el **APU en tierra**: se apaga y descarga su botella solo;\n- los **wastebins de los lavatorios**, con su propio extintor automático.\n\nEn los **motores** y las **bodegas** la descarga la hace la **tripulación**. La **aviónica** tiene detección de humo, pero **no tiene sistema de extinción**.","keyIdea":"Automática: solo el APU en tierra y los wastebins. Motores y bodegas, la tripulación. Aviónica, solo detección."}],"test":[{"id":"fir-1-t1","type":"mcq","question":"¿Qué sistemas del A320 tienen extinción automática de incendio?","options":["El APU en tierra y los wastebins de lavatory","Los motores y los cargos, sin intervención de tripulación","El avionics bay y los motores","Todos los compartimientos donde exista detección de humo"],"correct":0,"explanation":"Solo el APU en tierra, que se apaga y descarga su botella solo, y los wastebins de los lavatorios. En los motores y las bodegas descarga la tripulación.","taughtIn":["fir-1-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:xxg1m"}},{"id":"fir-1-t2","type":"mcq","question":"WHICH OF THE FOLLOWING HAVE AUTOMATIC FIRE EXTINGUISHING SYSTEMS?","options":["APU ON GROUND AND LAVATORY WASTE BINS.","APU ON GROUND, LAVATORY WASTE BINS AND AVIONICS BAY.","APU ON GROUND, AFT CARGO, FORWARD CARGO, LAVATORY WASTE BINS AND AVIONICS BAY.","LAVATORY WASTE BINS."],"correct":0,"explanation":"Solo el APU en tierra y los basureros de lavatorio cuentan con extinción automática; las bodegas de carga requieren accionamiento manual del pushbutton DISCH, y el compartimento de aviónica no tiene sistema de extinción instalado.","taughtIn":["fir-1-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1i87kxt"}},{"id":"fir-1-t3","type":"mcq","question":"THE AVIONICS COMPARTMENT IS THE ONLY AREA WHERE THERE IS NO FIRE EXTINGUISHING SYSTEM INSTALLED.","options":["TRUE.","FALSE."],"correct":0,"explanation":"Verdadero: el compartimento de aviónica cuenta con detección de humo (genera una alerta AVIONICS SMOKE), pero no tiene un sistema fijo de extinción instalado, a diferencia de motores, APU, bodegas de carga y basureros de lavatorio.","taughtIn":["fir-1-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:10k8um3"}},{"id":"fir-1-t4","type":"mcq","question":"¿Qué diferencia importante existe entre la protección del avionics bay y la del lavatory wastebin?","options":["Ambos disponen de detección y extinción fija automática de arquitectura equivalente","Avionics: smoke detection; lavatory wastebin: automatic extinguishing","El avionics bay utiliza extinción fija, mientras el wastebin solo tiene detección de humo","Ambos dependen exclusivamente de extintores portátiles utilizados por la tripulación"],"correct":1,"explanation":"La aviónica tiene detección de humo, pero no extinción; el wastebin del lavatorio tiene extinción automática. Detectar humo no significa tener una botella fija.","taughtIn":["fir-1-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:140niwv"}}]},
{"id":"fir-2","subject":"fuego","order":2,"kind":"lesson","level":1,"ident":"DET","title":"Engine and APU fire detection","goal":"Explicar cómo se detecta un fuego en los motores y el APU, cuándo aparece el fire warning y qué pasa si falla un loop.","intro":"Dos loops vigilan cada motor y el APU. Saber cuándo avisan evita falsas alarmas y alarmas perdidas.","minutes":5,"cards":[{"id":"fir-2-c1","title":"Two loops and an FDU","body":"Cada motor y el APU tienen un sistema de detección de fuego y sobretemperatura con:\n- **dos loops iguales, A y B, en paralelo**;\n- una **FDU** (Fire Detection Unit), que procesa sus señales.\n\nEn cada motor, los elementos sensores están en el **pylon y la nacelle**, en el **core** y en el **fan**. En el APU hay un elemento en su compartimiento.","diagram":{"alt":"Un motor con dos loops de detección, A y B, en paralelo, que pasan por el pylon y la nacelle, el core y el fan, y llegan a la FDU. La FDU da el fire warning si los dos loops detectan, si uno detecta y el otro está fallado, o si los dos se cortan con menos de 5 segundos de diferencia.","src":"assets/estaciones/diagramas/fir-loops.svg"},"keyIdea":"Dos loops en paralelo y una FDU; en el motor, pylon y nacelle, core y fan."},{"id":"fir-2-c2","title":"When the warning comes on","body":"La FDU da el **fire warning** si:\n- los **dos loops** detectan fuego, o\n- **uno** detecta fuego y el **otro está fallado**, o\n- los **dos loops se cortan con menos de 5 segundos** de diferencia: una llama puede romper los dos casi a la vez (flame effect), o\n- se hace un **test** en el panel FIRE.","keyIdea":"Warning: los dos loops, uno con el otro fallado, dos cortes en 5 s o un test."},{"id":"fir-2-c3","title":"One loop failed","body":"Si falla **un loop** (se corta o pierde su energía), aparece una **caution** de falla de ese loop, pero la detección **sigue**: el otro loop protege solo.\n\nPor ejemplo, si el STATUS muestra ENG 1 LOOP B como INOP SYS, el motor 1 sigue con detección por el loop A, y el motor 2, con sus dos loops.","keyIdea":"Un loop fallado: caution, y el otro sigue detectando."}],"test":[{"id":"fir-2-t1","type":"mcq","question":"¿Cómo está organizada la detección de incendio de los motores y del APU?","options":["Dos loops idénticos A y B conectados en paralelo","Cada motor tiene un loop y el APU tres loops independientes","Los motores dependen de detectores de humo y el APU de un loop térmico","Un único loop común protege ambos motores y el APU"],"correct":0,"explanation":"La arquitectura usa redundancia: dos loops vigilan cada motor y el APU. La lógica compara sus señales para evitar que una sola falla de detección deje al sistema sin protección o produzca una alarma espuria con facilidad.","taughtIn":["fir-2-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:v14h9r"}},{"id":"fir-2-t2","type":"mcq","question":"¿Qué zonas del motor son vigiladas por los elementos de los fire detection loops?","options":["Pylon/nacelle, core y fan","Pylon/nacelle y core solamente","Core y fan solamente","Fan y thrust reverser solamente"],"correct":0,"explanation":"Los elementos sensores de los loops vigilan el pylon y la nacelle, el core y el fan del motor.","taughtIn":["fir-2-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:1f53u21"}},{"id":"fir-2-t3","type":"mcq","question":"Además de los dos detection loops, ¿qué elemento procesa las señales de incendio de cada motor y del APU?","options":["Una Fire Detection Unit (FDU)","Un Smoke Detection Control Unit","El Flight Warning Computer","El Bleed Monitoring Computer"],"correct":0,"explanation":"Cada sistema de detección de motor/APU incluye dos loops y una FDU. La FDU procesa las señales y aplica la lógica de warning/fault; no debe confundirse con los computadores de detección de humo de otras zonas.","taughtIn":["fir-2-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:13eyeqx"}},{"id":"fir-2-t4","type":"mcq","question":"¿Qué ocurre si se producen roturas en ambos fire detection loops dentro de 5 segundos entre sí?","options":["Se genera solamente una cautela de loop fault","Genera un fire warning por posible flame effect","La detección queda inhibida durante 5 segundos","Se dispara automáticamente una botella extintora"],"correct":1,"explanation":"Una llama puede dañar físicamente ambos loops casi al mismo tiempo. Por eso la lógica no interpreta dos roturas muy próximas como dos fallas eléctricas independientes: las trata como un indicio compatible con fuego y genera la advertencia correspondiente.","taughtIn":["fir-2-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:1vwcgkn"}},{"id":"fir-2-t5","type":"mcq","question":"Si falla un solo fire detection loop de un motor, ¿se pierde la capacidad de detectar un incendio en ese motor?","options":["Sí; ambos loops deben estar operativos para que el sistema genere cualquier fire warning","No; el loop restante mantiene detección y la falla del otro genera una cautela","Sí; salvo cuando el APU está running y alimenta el sistema de fire detection","No; pero únicamente durante takeoff y landing, cuando la lógica tiene prioridad"],"correct":1,"explanation":"Los loops son redundantes. Si uno falla, la FDU reconoce la falla y el otro loop sigue proporcionando protección. De hecho, la lógica permite generar un fire warning si el loop operativo detecta fuego mientras el otro está fallado. Esa es la razón de tener dos canales en paralelo.","taughtIn":["fir-2-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:1hptpnb"}},{"id":"fir-2-t6","type":"mcq","question":"STATUS PAGE: INOP SYS INDICATES ENG 1 LOOP B.","options":["ONE FIRE DETECTION LOOP HAS FAILED. FIRE DETECTION FOR BOTH ENGINES IS NOT AVAILABLE.","ONE DETECTION LOOP FOR ENGINE 1 HAS FAILED. FIRE DETECTION FOR BOTH ENGINES IS STILL AVAILABLE.","ONE FIRE DETECTION LOOP OF ENGINE 1 HAS FAILED. FIRE DETECTION FOR ENGINE 1 IS INOPERATIVE.","BOTH FIRE DETECTION LOOPS OF ENGINE 1 HAVE FAILED. FIRE DETECTION FOR ENGINE 1 IS INOPERATIVE."],"correct":1,"explanation":"Si solo falla el loop B del motor 1, el motor 1 conserva su loop A operativo y sigue teniendo detección de fuego (con redundancia reducida); el motor 2, al no verse afectado, mantiene sus dos loops normales. Por lo tanto, la detección de fuego sigue disponible para ambos motores.","taughtIn":["fir-2-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1113l1a"}}]},
{"id":"fir-3","subject":"fuego","order":3,"kind":"lesson","level":1,"ident":"SMK","title":"Smoke detection: avionics and lavatories","goal":"Explicar dónde está el detector de humo de la aviónica y de los lavatorios, qué alertas da y qué extinción hay.","intro":"En la aviónica y en los lavatorios no hay loops de fuego: hay detectores de humo en el aire que se extrae.","minutes":5,"cards":[{"id":"fir-3-c1","title":"Avionics smoke","body":"En el **ducto de extracción** de la ventilación de aviónica hay **un detector de humo**. Si detecta humo **más de 5 segundos**:\n- suena el **Single Chime** y destella el **MASTER CAUTION**;\n- aparece la alerta **AVIONICS SMOKE** en el ECAM;\n- se enciende la luz **SMOKE** del botón GEN 1 LINE (panel EMER ELEC PWR);\n- se encienden las luces **FAULT** de BLOWER y EXTRACT (panel VENTILATION).","keyIdea":"Un detector en la extracción de aviónica; más de 5 s: SC, MASTER CAUT, AVIONICS SMOKE y luces."},{"id":"fir-3-c2","title":"Lavatory smoke","body":"Cada lavatorio tiene **un detector de humo** en su **ducto de extracción**. La señal va a una unidad de control (SDCU, o el CIDS con su función de detección de humo), que la envía al Flight Warning Computer: la alerta aparece **en la cabina de mando y en la cabina de pasajeros**.\n\nEl **wastebin** de cada lavatorio tiene su **extintor automático**.","diagram":{"alt":"Dos casos de detección de humo. Aviónica: un detector en el ducto de extracción; con humo por más de 5 segundos, alerta AVIONICS SMOKE, Single Chime y MASTER CAUTION. Lavatorio: un detector en el ducto de extracción, señal a la SDCU o al CIDS y alerta en la cabina de mando y en la de pasajeros; el wastebin tiene extinción automática.","src":"assets/estaciones/diagramas/fir-humo.svg"},"keyIdea":"Lavatorio: un detector en la extracción, alerta en cockpit y cabina; wastebin con extintor automático."}],"test":[{"id":"fir-3-t1","type":"mcq","question":"¿Cómo detecta humo el avionics bay?","options":["Mediante fire loops instalados alrededor de los principales computadores de aviónica","Mediante un smoke detector situado en el ducto de extracción de ventilación","Mediante los smoke detectors del forward cargo, que comparten la misma zona","No dispone de detección automática; depende de olor o indicación visual en cockpit"],"correct":1,"explanation":"La estrategia en aviónica es vigilar el aire que se extrae del compartimiento. Un detector en ese ducto permite reconocer que humo está siendo evacuado desde los equipos, y entonces el sistema genera las alertas y reconfiguraciones de ventilación correspondientes.","taughtIn":["fir-3-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:14sji4b"}},{"id":"fir-3-t2","type":"mcq","question":"Si el detector del avionics bay detecta humo durante más de 5 segundos, ¿qué tipo de respuesta de cabina se genera?","options":["CRC y Master Warning roja, sin mensajes adicionales en ECAM","Single Chime, Master Caution, AVIONICS SMOKE en ECAM y luces asociadas","Ninguna indicación hasta que se produzca también una falla de computadores","Descarga automática de un agente fijo de extinción dentro del avionics bay"],"correct":1,"explanation":"El humo de aviónica se presenta como una cautela que además orienta a la tripulación hacia los paneles implicados en la reconfiguración eléctrica y de ventilación. El objetivo no es solo avisar que hay humo, sino ayudar a aislar su fuente y controlar el flujo de aire.","taughtIn":["fir-3-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:nyp9u3"}},{"id":"fir-3-t3","type":"mcq","question":"¿Cómo detecta humo el sistema de un lavatory y dónde genera las alertas?","options":["Usa dos detectores ópticos y alerta solo en cabina de pasajeros","Detector en extraction duct; alerta en cockpit y cabin","Usa un detector térmico y alerta únicamente en ECAM","No tiene detección; solo posee extinción automática del wastebin"],"correct":1,"explanation":"El detector está colocado en el flujo de extracción para que el aire del lavatory pase por él. Si detecta humo, la señal se procesa a través del SDCU/CIDS y llega al sistema de advertencias, de modo que tanto los pilotos como la tripulación de cabina sean alertados.","taughtIn":["fir-3-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:175av2y"}},{"id":"fir-3-t4","type":"mcq","question":"¿Qué protección contra incendio tiene el wastebin de cada lavatory?","options":["Solo detección de humo, sin sistema fijo de extinción","Un sistema automático de extinción propio","Extinción manual comandada desde el cockpit","Agente compartido con el sistema del APU"],"correct":1,"explanation":"Cada lavatory wastebin dispone de un sistema automático de extinción. Debe distinguirse de la detección de humo del lavatory.","taughtIn":["fir-3-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:11pevyn"}},{"id":"fir-3-t5","type":"mcq","question":"EACH LAVATORY IS EQUIPPED WITH:","options":["TWO SMOKE DETECTORS AND ONE SMOKE DETECTION CONTROL UNIT.","ONE SMOKE DETECTOR AND ONE SMOKE DETECTION CONTROL UNIT.","ONE SMOKE DETECTOR, AND FOR LAVATORY WASTE BINS, AN AUTOMATICALLY DISCHARGING FIRE EXTINGUISHER.","TWO SMOKE DETECTORS AND TWO AUTOMATICALLY DISCHARGING FIRE EXTINGUISHERS."],"correct":2,"explanation":"Cada lavatorio tiene un único detector de humo (no doble loop, a diferencia de motor/APU), y el basurero del lavatorio incorpora su propio extintor de descarga automática, que actúa por sí solo ante un incendio sin requerir acción de la tripulación.","taughtIn":["fir-3-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:oukwcr"}},{"id":"fir-3-t6","type":"mcq","question":"IN THE EVENT A LAVATORY SMOKE DETECTOR DETECTS SMOKE:","options":["WARNINGS WILL BE GENERATED ONLY IN THE COCKPIT.","WARNINGS WILL BE GENERATED ONLY ON THE FLIGHT DECK.","WARNINGS WILL BE GENERATED IN THE COCKPIT AND IN THE CABIN."],"correct":2,"explanation":"La detección de humo en un lavatorio genera alerta tanto en la cabina de mando como en la cabina de pasajeros, ya que la tripulación de cabina también necesita saberlo para actuar sobre el lavatorio directamente.","taughtIn":["fir-3-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:6jhxig"}}]},
{"id":"fir-4","subject":"fuego","order":4,"kind":"lesson","level":2,"ident":"EFP","title":"ENG FIRE pushbutton and agents","goal":"Explicar qué hace el ENG FIRE pb al soltarlo, cuándo se pueden descargar los agentes y qué indican sus luces.","intro":"El ENG FIRE pb no apaga el fuego: aísla el motor y prepara las botellas.","minutes":5,"cards":[{"id":"fir-4-c1","title":"Releasing the ENG FIRE pb","body":"El **ENG 1(2) FIRE pb** está adentro y con guarda. Al presionarlo, sale (released) y, para ese motor:\n- **silencia** la alarma sonora;\n- **arma los squibs** de los extintores;\n- cierra la **LP fuel valve**, la **hydraulic fire shut off valve**, la **bleed valve** y la **pack flow control valve**;\n- **corta la energía del FADEC** y **desactiva el IDG**.\n\nEs decir, **aísla** el motor del combustible, la hidráulica, el neumático y la electricidad.","diagram":{"alt":"El ENG FIRE pb al soltarlo: silencia la alarma y arma los squibs; cierra la LP fuel valve, la hydraulic fire shut off valve, la bleed valve y la pack flow control valve; corta el FADEC y desactiva el IDG. Debajo, los AGENT 1 y AGENT 2, con sus luces SQUIB blanca y DISCH ámbar.","src":"assets/estaciones/diagramas/fir-engfire.svg"},"keyIdea":"Soltar el ENG FIRE pb: silencia, arma los squibs y aísla combustible, hidráulica, bleed y electricidad."},{"id":"fir-4-c2","title":"Two agents per engine","body":"Cada motor tiene **dos botellas** de extintor. Sus **AGENT 1 y AGENT 2** se activan **cuando se suelta el ENG FIRE pb**; un toque breve descarga esa botella.\n- **SQUIB** (blanca): se enciende al soltar el ENG FIRE pb, para identificar el AGENT que se puede usar.\n- **DISCH** (ámbar): la botella **perdió presión**, es decir, se descargó.","keyIdea":"Dos botellas por motor; AGENT activos al soltar el FIRE pb; SQUIB = armado, DISCH = descargada."},{"id":"fir-4-c3","title":"The red lights","body":"La luz roja del **ENG FIRE pb** se enciende mientras el **fire warning** de ese motor esté activo, **esté el botón adentro o afuera**: se apaga solo cuando el fuego ya no se detecta.\n\nEn el panel ENG MASTER, la luz roja **FIRE** de cada motor **identifica el motor que hay que apagar**.","keyIdea":"Luz roja del FIRE pb: mientras haya fire warning. FIRE del ENG MASTER: el motor que se apaga."}],"test":[{"id":"fir-4-t1","type":"mcq","question":"Al liberar el ENG 1(2) FIRE pushbutton, ¿qué busca conseguir el avión antes de descargar agente extintor?","options":["Aumentar fuel flow y bleed para enfriar componentes antes de la descarga del agente","Aislar fuel, hydraulic, pneumatic y electrical sources, silenciar warning y armar squibs","Desplegar RAT, mantener IDG conectado y asegurar alimentación eléctrica al motor afectado","Cerrar únicamente la engine bleed valve y mantener el resto de fuentes para refrigeración"],"correct":1,"explanation":"La primera defensa ante un incendio de motor es quitarle fuentes que puedan alimentarlo y aislar sus conexiones con el resto del avión. Por eso el FIRE pb corta combustible, hidráulico, bleed, alimentación FADEC e IDG, y al mismo tiempo arma las botellas. La descarga de agente es una acción posterior.","taughtIn":["fir-4-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:1cxmwd"}},{"id":"fir-4-t2","type":"mcq","question":"THE ENGINE EXTINGUISHING AGENT SWITCH IS ARMED WHEN:","options":["THE DISCH LIGHT IS ON.","THE ENGINE FIRE SWITCH ILLUMINATES.","THE ENGINE FIRE SWITCH IS RELEASED OUT."],"correct":2,"explanation":"El armado de los switches de agente extintor de motor ocurre cuando se libera hacia afuera (released out) el pushbutton guardado de fuego de ese motor; ese es el paso previo necesario antes de poder descargar el agente.","taughtIn":["fir-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:u7d6e4"}},{"id":"fir-4-t3","type":"mcq","question":"¿Qué significa que se encienda en ámbar la indicación DISCH de un AGENT pb de incendio?","options":["Que el FIRE pushbutton correspondiente fue liberado y el squib quedó armado","Que la botella extintora correspondiente ha perdido presión","Que el detector de incendio asociado quedó inoperativo","Que el agente se está descargando en ese instante"],"correct":1,"explanation":"La indicación ámbar DISCH aparece cuando la botella extintora correspondiente ha perdido presión. La indicación describe el estado de presión de la botella.","taughtIn":["fir-4-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:1482r57"}},{"id":"fir-4-t4","type":"mcq","question":"En un AGENT pushbutton, ¿qué diferencia conceptual hay entre SQUIB y DISCH?","options":["SQUIB = botella descargada; DISCH = circuito armado","SQUIB = circuito armado; DISCH = pérdida de presión","SQUIB = smoke warning; DISCH = fire warning","SQUIB = detector activo; DISCH = loop aislado"],"correct":1,"explanation":"SQUIB y DISCH no representan la misma etapa. SQUIB ayuda a identificar el agente que puede activarse tras liberar el FIRE pb; DISCH informa sobre la presión de la botella. Entender esa secuencia evita memorizar luces sin saber qué estado físico representa cada una.","taughtIn":["fir-4-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:2s9kyx"}},{"id":"fir-4-t5","type":"mcq","question":"¿De qué depende que la luz roja ENG 1(2) FIRE del FIRE pushbutton permanezca encendida?","options":["De que el pushbutton esté físicamente liberado","Que siga activa la condición de fire warning","De que la primera botella esté descargada","De que el motor esté por debajo de idle"],"correct":1,"explanation":"La luz roja informa la existencia del fire warning, no la posición mecánica del pushbutton. Liberar el FIRE pb ejecuta acciones de aislamiento, pero la indicación roja solo desaparece cuando deja de existir la condición que originó la advertencia.","taughtIn":["fir-4-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:1qra2c3"}},{"id":"fir-4-t6","type":"mcq","question":"¿Qué función tiene la luz roja ENG 1(2) FIRE del ENG MASTER panel?","options":["Indicar qué botella extintora debe descargarse primero","Identificar el motor que debe apagarse","Indicar que el IDG del motor está todavía conectado","Confirmar que el motor ya está completamente aislado"],"correct":1,"explanation":"La luz roja ENG 1(2) FIRE identifica el motor que debe apagarse en caso de incendio. No es una indicación de descarga de agente ni de que el motor ya esté aislado.","taughtIn":["fir-4-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:ynr0t0"}}]},
{"id":"fir-5","subject":"fuego","order":5,"kind":"lesson","level":2,"ident":"APF","title":"APU fire","goal":"Explicar cómo se protege el APU contra fuego en tierra y en vuelo, cómo se avisa afuera y qué hace el APU FIRE pb.","intro":"El APU tiene una sola botella, pero en tierra se defiende solo.","minutes":5,"cards":[{"id":"fir-5-c1","title":"On the ground: automatic","body":"El APU tiene **una botella** de extintor, con dos squibs. Si se detecta un **fuego del APU en tierra**:\n- el APU **se apaga solo**;\n- la botella **se descarga sola 3 segundos después** de aparecer el fire warning.\n\nPara el personal de tierra, en el panel de energía externa se enciende la luz roja **APU FIRE** y suena una **bocina exterior**; la luz se apaga cuando el fuego se extingue.","diagram":{"alt":"Fuego del APU. En tierra: se apaga solo, la botella se descarga sola 3 segundos después del warning, y afuera se enciende la luz APU FIRE y suena la bocina. En vuelo: la tripulación suelta el APU FIRE pb y descarga el agente. El APU tiene una sola botella.","src":"assets/estaciones/diagramas/fir-apu.svg"},"keyIdea":"En tierra: apagado y descarga automática a los 3 s; luz APU FIRE y bocina afuera."},{"id":"fir-5-c2","title":"In flight: crew action","body":"En **vuelo**, el APU no se apaga ni se extingue solo: la tripulación suelta el **APU FIRE pb** y descarga el **AGENT** (el AGENT se activa al soltar el APU FIRE pb).","keyIdea":"En vuelo, apagado y descarga manuales."},{"id":"fir-5-c3","title":"APU FIRE pb","body":"Al soltar el **APU FIRE pb**:\n- se **apaga el APU** y se silencia la alarma;\n- se **arma el squib** de la botella;\n- se cierran la LP fuel valve y la APU fuel pump;\n- se cierran la **APU bleed valve** y la **crossbleed valve**, y se desactiva el APU GEN.\n\nComo en los motores, su luz roja sigue encendida mientras haya fire warning, esté el botón como esté.","keyIdea":"APU FIRE pb: apaga, silencia, arma el squib y aísla combustible, bleed y generador."}],"test":[{"id":"fir-5-t1","type":"mcq","question":"Si el sistema detecta un incendio del APU con el avión en tierra y los motores parados, ¿qué protección automática se activa?","options":["Solo aparece una indicación visual; la tripulación debe hacer toda la extinción","El APU se apaga automáticamente y la botella se descarga automáticamente","El APU sigue funcionando para alimentar los sistemas hasta que la tripulación lo apague","Solo se cierra la APU bleed valve, sin descargar agente"],"correct":1,"explanation":"En tierra, ante un fuego del APU, el APU se apaga solo y la botella se descarga sola. El apagado automático por fuego es en tierra con los motores detenidos.","taughtIn":["fir-5-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:ony9tw"}},{"id":"fir-5-t2","type":"mcq","question":"Tras detectarse un incendio del APU en tierra, ¿cuándo se descarga automáticamente la botella extintora?","options":["Inmediatamente","Después de 1 s","Después de 3 s","Después de 10 s"],"correct":2,"explanation":"El sistema primero inicia la respuesta automática y luego aplica un retardo de 3 segundos antes de descargar el agente. Ese retardo forma parte de la lógica diseñada de la protección automática en tierra; no es un tiempo que la tripulación deba cronometrar manualmente.","taughtIn":["fir-5-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:1ejk01b"}},{"id":"fir-5-t3","type":"mcq","question":"¿Cómo se alerta al personal de tierra cuando se detecta un incendio del APU?","options":["Únicamente mediante mensajes ECAM dentro de la cabina","APU FIRE light exterior y external horn","Mediante una luz ámbar en el tren de nariz","No existe alerta externa automática"],"correct":1,"explanation":"La protección del APU en tierra tiene que advertir también a personas que están fuera del cockpit. Por eso el sistema utiliza una indicación visual externa y una señal acústica exterior, además de las indicaciones de cabina.","taughtIn":["fir-5-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:1dykpni"}},{"id":"fir-5-t4","type":"mcq","question":"IF THERE IS AN APU FIRE IN FLIGHT THE APU:","options":["WILL AUTOMATICALLY SHUT DOWN AND THE FIRE BOTTLE WILL DISCHARGE.","MUST BE SHUT DOWN MANUALLY AND THE AGENT MANUALLY DESCHARGED.","MUST BE SHUT DOWN MANUALLY BUT THE FIRE BOTTLE WILL DISCHARGE AUTOMATICALLY."],"correct":1,"explanation":"A diferencia de la protección automática en tierra, un fuego de APU en vuelo exige que la tripulación apague el APU y descargue el agente manualmente; la protección automática está reservada para operación en tierra.","taughtIn":["fir-5-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1s8zk0l"}},{"id":"fir-5-t5","type":"mcq","question":"Al liberar el APU FIRE pushbutton, ¿qué conjunto de acciones ordena el sistema?","options":["Arma el squib y mantiene fuel/bleed y generator conectados","Apaga APU, silencia warning, arma squib, aísla fuel/bleed y generator","Descarga el agente, mantiene fuel/bleed abiertos y conserva el generator conectado","Apaga APU y generator, pero mantiene fuel/bleed disponibles"],"correct":1,"explanation":"El FIRE pushbutton no es el botón de descarga del agente: su función principal es aislar el APU como fuente de combustible, aire y energía, además de prepararlo para la extinción. El agente se descarga después mediante el AGENT pb (salvo la lógica automática de incendio en tierra).","taughtIn":["fir-5-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:1rflq5r"}},{"id":"fir-5-t6","type":"mcq","question":"WHEN THE APU FIRE SWITCH IS RELEASED OUT:","options":["SHUTS DOWN THE APU.","ARMS THE SQUIB ON THE APU FIRE EXTINGUISHER.","THE APU BLEED AND CROSS BLEED VALVES ARE CLOSED.","ALL THE ABOVE."],"correct":3,"explanation":"Liberar el pushbutton de fuego del APU produce simultáneamente tres efectos: apaga el APU, arma el squib de la botella extintora, y cierra las válvulas de bleed y cross bleed del APU para aislarlo del resto del sistema neumático.","taughtIn":["fir-5-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:155rcth"}}]},
{"id":"fir-6","subject":"fuego","order":6,"kind":"lesson","level":2,"ident":"TST","title":"Fire tests","goal":"Explicar qué muestran los tests de fuego de motor y del APU, y qué cambia si solo hay baterías.","intro":"El test de fuego prueba de verdad la detección y la extinción. Hay que saber qué esperar ver.","minutes":5,"cards":[{"id":"fir-6-c1","title":"ENG FIRE TEST","body":"El **ENG 1(2) FIRE TEST** prueba la detección y la extinción de ese motor. Al presionarlo:\n- suena el **CRC** y destellan los **MASTER WARNING**;\n- aparece la alerta **ENG FIRE** en el ECAM;\n- en el panel FIRE: el **ENG FIRE pb en rojo**, las **SQUIB** en blanco (si hay energía para la descarga) y las **DISCH** en ámbar;\n- en el panel ENG MASTER: las luces **FIRE** en rojo.","diagram":{"alt":"Lo que se ve en el test de fuego: CRC y MASTER WARNING, alerta en el ECAM, el FIRE pb en rojo, SQUIB en blanco y DISCH en ámbar, y en el motor también la luz FIRE del panel ENG MASTER. Con solo baterías, el test del APU en tierra: SQUIB y DISCH sí, sin alerta en el ECAM, y el APU FIRE pb encendido a medias.","src":"assets/estaciones/diagramas/fir-test.svg"},"keyIdea":"Test de motor: CRC, MASTER WARNING, ENG FIRE en el ECAM, FIRE pb rojo, SQUIB, DISCH y FIRE del ENG MASTER."},{"id":"fir-6-c2","title":"APU FIRE TEST","body":"El **APU FIRE TEST** da lo mismo para el APU: CRC, MASTER WARN, **APU FIRE** en el ECAM, el APU FIRE pb en rojo, SQUIB y DISCH.\n\nCuidado en tierra: si el test dura **más de 3 segundos**, el APU **puede apagarse solo**.","keyIdea":"Test del APU: como el de motor; en tierra, más de 3 s puede apagar el APU."},{"id":"fir-6-c3","title":"On batteries only","body":"El APU FIRE TEST **se puede hacer en tierra con solo baterías**, pero se ve distinto:\n- las luces **SQUIB y DISCH** se encienden;\n- **no hay alertas en el ECAM** (tampoco MASTER WARN);\n- el **APU FIRE pb se enciende a medias**: uno de sus juegos de lámparas no tiene energía.","keyIdea":"Con baterías: SQUIB y DISCH sí, sin ECAM, y el APU FIRE pb a medias."}],"test":[{"id":"fir-6-t1","type":"mcq","question":"Durante un ENG FIRE TEST con alimentación disponible, ¿qué conjunto de indicaciones confirma que se está probando el sistema?","options":["Solo ENG FIRE pb y Master Warning, sin mensajes ECAM ni indicación de bottles","CRC/Master Warning, ENG FIRE en ECAM y luces FIRE/SQUIB/DISCH asociadas","Descarga automática de AGENT 1 y aparición inmediata de DISCH en ambos bottles","Master Caution ámbar y FIRE DET FAULT, sin CRC ni warning rojo"],"correct":1,"explanation":"La prueba recorre tanto la cadena de detección como la de indicación/extinción. Por eso activa señales auditivas, ECAM, luces del FIRE panel y del pedestal, además de los indicadores asociados a los agentes. Es una prueba funcional amplia, no un simple test de lámparas.","taughtIn":["fir-6-c1"],"source":{"bank":"fcom","system":"fire","appId":"fire:1ajildu"}},{"id":"fir-6-t2","type":"mcq","question":"¿Puede un APU FIRE TEST provocar el apagado automático del APU en tierra?","options":["No; el fire test no interactúa con la lógica de APU shutdown","Sí; si el test se mantiene durante más de 3 s","Sí; si el test se mantiene durante más de 1 s","Sí; pero solo después de 10 s de test continuo"],"correct":1,"explanation":"Sí: en tierra, si el APU FIRE TEST se mantiene más de 3 segundos, el APU puede apagarse solo. El test prueba los circuitos reales de protección.","taughtIn":["fir-6-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:x73bu4"}},{"id":"fir-6-t3","type":"mcq","question":"¿Puede realizarse el APU FIRE TEST en tierra cuando solo las baterías alimentan la red eléctrica?","options":["No; requiere AC power para ambos loops","Sí; con indicaciones distintas/reducidas","Sí; solo si el APU ya está en marcha","No; solo mantenimiento puede probarlo"],"correct":1,"explanation":"Sí, se puede hacer con solo baterías, pero las indicaciones no son las mismas que con la red completa.","taughtIn":["fir-6-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:1hw5ojg"}},{"id":"fir-6-t4","type":"mcq","question":"Durante un APU FIRE TEST en tierra con solo baterías, ¿qué diferencia principal debe esperarse respecto de una prueba con alimentación completa?","options":["No aparece ninguna indicación de SQUIB ni DISCH","SQUIB y DISCH; sin ECAM warning; APU FIRE pb parcialmente iluminado","El MASTER WARN y el ECAM funcionan normalmente, pero no se prueba el squib","La botella extintora se descarga físicamente"],"correct":1,"explanation":"Con solo baterías se encienden SQUIB y DISCH, pero no hay alertas en el ECAM, y el APU FIRE pb se enciende a medias porque uno de sus juegos de lámparas no tiene energía.","taughtIn":["fir-6-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:8pqkmg"}},{"id":"fir-6-t5","type":"mcq","question":"CAN THE APU FIRE TEST BE PERFORME DURING BETTERY POWER ONLY?","options":["YES.","NO."],"correct":0,"explanation":"Sí: el APU FIRE TEST se puede hacer en tierra con solo baterías, con indicaciones reducidas.","taughtIn":["fir-6-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:ljerlj"}},{"id":"fir-6-t6","type":"mcq","question":"IF YOU PERFORM THE APU FIRE TEST WITH ONLY DC POWER AVAILABLE, YOU GET THE MASTER WARN ON THE ECAM.","options":["TRUE.","FALSE."],"correct":1,"explanation":"Falso: con solo baterías no hay alertas en el ECAM; se encienden SQUIB y DISCH y el APU FIRE pb a medias.","taughtIn":["fir-6-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:16bzf7a"}}]},
{"id":"fir-7","subject":"fuego","order":7,"kind":"lesson","level":2,"ident":"CRG","title":"Cargo smoke","goal":"Explicar cómo se detecta humo en las bodegas, qué hace el sistema solo y cómo se descarga el agente.","intro":"En las bodegas el sistema detecta y aísla solo, pero descargar el agente es decisión de la tripulación.","minutes":6,"cards":[{"id":"fir-7-c1","title":"Detectors and warning","body":"En el A320, las bodegas tienen **detectores de humo** en las cavidades del techo: **dos adelante y cuatro atrás**, cada uno unido a uno de **dos loops**. Una unidad de control de **dos canales** (SDCU, o el CIDS con su función de detección de humo) recibe sus señales y avisa al ECAM.\n\nEl warning de humo en una cavidad aparece si **los dos detectores** detectan humo, o si uno detecta y el otro no funciona. Se enciende la luz roja **SMOKE** con su alerta del ECAM.","keyIdea":"Dos detectores adelante y cuatro atrás, dos loops; warning con los dos o con uno y el otro fallado."},{"id":"fir-7-c2","title":"Automatic isolation","body":"Con el warning de humo, el sistema **cierra solo las isolation valves** de la ventilación de la bodega y **detiene el extraction fan**: así no se sigue moviendo aire por la bodega.\n\nLa **descarga** del agente, en cambio, **no es automática**: la tripulación presiona el **DISCH pb** de la bodega afectada (FWD o AFT).","diagram":{"alt":"Humo en una bodega: los detectores avisan, se enciende la luz SMOKE con su alerta del ECAM, y el sistema cierra solo las isolation valves y detiene el extraction fan. La tripulación presiona el DISCH pb de esa bodega; la botella descarga en unos 60 segundos y se enciende la luz DISCH.","src":"assets/estaciones/diagramas/fir-carga.svg"},"keyIdea":"Solo: cierra la ventilación y para el fan. La descarga: la tripulación con el DISCH pb."},{"id":"fir-7-c3","title":"One or two bottles","body":"La cantidad de botellas **depende del MSN**:\n- **hasta el 11597** (con algunas excepciones): **una botella** con dos discharge heads, una por bodega. Descarga en unos 60 segundos y mantiene el agente unos 60 minutos. Al vaciarse, se encienden las luces **DISCH** ámbar;\n- **desde el 11629**: **dos botellas**; la segunda descarga de a poco con un sistema de dosificación, y sus luces son **BTL 1 y BTL 2**.","keyIdea":"Hasta el MSN 11597, una botella para las dos bodegas; desde el 11629, dos botellas."}],"test":[{"id":"fir-7-t1","type":"mcq","question":"THE AFT CARGO COMPARTMENT SMOKE DETECTION SYSTEM CONSISTS OF:","options":["A DUAL LOOP SMOKE DETECTOR.","FOUR SMOKE DETECTORS AND A TWO CHANNEL SMOKE DETECTION CONTROL UNIT.","ONE SMOKE DETECTOR, ONE SMOKE DETECTION CONTROL UNIT AND TWO AUTOMATICALLY DISCHARGING FIRE EXTINGUISHERS.","THREE SMOKE DETECTORS, ONE SMOKE DETECTION CONTROL UNIT AND TWO AUTOMATICALLY DISCHARGING FIRE EXTINGUISHERS."],"correct":1,"explanation":"En el A320, la bodega trasera tiene cuatro detectores de humo (y la delantera dos), unidos a dos loops, con una unidad de control de dos canales.","taughtIn":["fir-7-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1qe894p"}},{"id":"fir-7-t2","type":"mcq","question":"¿Qué ocurre automáticamente con la ventilación del cargo cuando se activa un cargo smoke warning?","options":["Abren cargo isolation valves y aumenta el extraction flow","Cierran cargo isolation valves y se detiene extraction fan","Mantienen cargo ventilation hasta que la tripulación pulse DISCH","Abren RAM AIR y mantienen extraction fan funcionando"],"correct":1,"explanation":"Ante humo, seguir moviendo aire por el compartimiento podría alimentar o distribuir el incendio y transportar humo. Por eso el sistema aísla el cargo y detiene la extracción como parte de la respuesta automática, antes de que la tripulación decida la descarga del agente.","taughtIn":["fir-7-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:1ah6cpx"}},{"id":"fir-7-t3","type":"mcq","question":"Cuando se confirma humo en un compartimiento de carga, ¿la descarga del agente extintor se inicia automáticamente?","options":["Sí; la detección de humo inicia automáticamente la descarga en cualquier cargo compartment","No; la tripulación selecciona el FWD o AFT DISCH pushbutton correspondiente","Sí; pero únicamente cuando la detección ocurre con la aeronave en tierra","No; porque los cargo compartments no disponen de sistema fijo de extinción"],"correct":1,"explanation":"La detección de humo sí automatiza acciones de aislamiento y ventilación, pero la descarga del agente de cargo requiere la selección del DISCH pb del compartimiento afectado. Esa separación evita confundir detección automática con extinción automática.","taughtIn":["fir-7-c2"],"source":{"bank":"fcom","system":"fire","appId":"fire:17k1bmy"}},{"id":"fir-7-t4","type":"mcq","question":"IN THE EVENT AND AFT CARGO COMPARTMENT SMOKE DETECTOR DETECTS SMOKE:","options":["EXTINGUISHING IS AUTOMATIC.","EXTINGUISHING IS AUTOMATIC ONLY WHILE ON THE GROUND.","THE CREW MUST DEPRESS THE APPROPRIATE DISCH SWITCH."],"correct":2,"explanation":"A diferencia de los basureros de lavatorio (extinción automática), la extinción del fuego en la bodega de carga requiere que la tripulación presione manualmente el pushbutton DISCH correspondiente; no es un proceso automático.","taughtIn":["fir-7-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1kh8tvr"}},{"id":"fir-7-t5","type":"mcq","question":"¿Es universal la cantidad de botellas de extinción instaladas para los compartimientos de carga en todos los A320?","options":["Sí; la familia usa una bottle fija para todos los MSN","No; puede haber una o dos bottles según MSN/effectivity","Sí; salvo configuraciones A319 que usan siempre dos bottles","No; la configuración normal usa siempre dos bottles por compartment"],"correct":1,"explanation":"No: según el MSN, hay una botella con dos discharge heads (hasta el 11597, con algunas excepciones) o dos botellas (desde el 11629).","taughtIn":["fir-7-c3"],"source":{"bank":"fcom","system":"fire","appId":"fire:rppm4b"}},{"id":"fir-7-t6","type":"mcq","question":"WITH REFERENCE TO CARGO COMPARTMENT FIRE EXTINGUISHING, WHICH STATEMENT IS TRUE?","options":["THERE ARE TWO FIRE BOTTLES, ONE FR THE FWD COMPARTMENT AND ONE FOR THE AFT.","THERE IS ONLY ONE FIRE BOTTLE, PRESSING EITHER DISCH PUSH BUTTON DISCHARGES IT INTO BOTH COMPARTEMENTS.","THERE IS ONLY ONE FIRE BOTTLE, WHEN IT IS DISCHARGED BOTH AMBER DISCH LIGHTS COME ON.","THERE ARE TWO FIRE BOTTLES, WHEN THE DISCH PUSHBUTTON IS PRESSED, THEY ARE BOTH DISCHARGED INTO THE APPROPRIATE COMPARTMENT."],"correct":2,"explanation":"Respuesta del examen: una sola botella, y al descargarse se encienden las luces DISCH. Así es en los MSN hasta el 11597 (con algunas excepciones). Desde el 11629 hay dos botellas, con luces BTL 1 y BTL 2.","taughtIn":["fir-7-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:m630ca"}}]},
{"id":"fir-8","subject":"fuego","order":8,"kind":"lesson","level":3,"ident":"ENF","title":"Engine fire procedure","goal":"Explicar las acciones ante un ENG FIRE en vuelo y en tierra, y por qué se espera antes de descargar el agente.","intro":"Uno de los procedimientos que más se pregunta. Importa el orden y el porqué.","minutes":6,"cards":[{"id":"fir-8-c1","title":"In flight","body":"Con **ENG 1(2) FIRE** en vuelo (**LAND ASAP**):\n- **THR LEVER** del motor afectado en **IDLE**;\n- **ENG MASTER** en **OFF** (se cierran las LP y HP valves);\n- **ENG FIRE pb**: **PUSH** (se silencia la alarma y se corta el FADEC);\n- **AGENT 1** después de **10 segundos**: DISCH;\n- avisar al **ATC**;\n- si sigue el fuego **30 segundos después** del AGENT 1: **AGENT 2**.\n\nNo se vuelve a arrancar ese motor.","diagram":{"alt":"Las acciones ante ENG FIRE en vuelo, en orden: THR LEVER del motor afectado en IDLE, ENG MASTER en OFF, ENG FIRE pb PUSH, AGENT 1 después de 10 segundos, ATC NOTIFY y, si el fuego sigue 30 segundos después, AGENT 2. LAND ASAP.","src":"assets/estaciones/diagramas/fir-engfire-vuelo.svg"},"keyIdea":"THR IDLE, MASTER OFF, FIRE pb, AGENT 1 a los 10 s, ATC, AGENT 2 a los 30 s si sigue."},{"id":"fir-8-c2","title":"Why wait 10 seconds","body":"Los 10 segundos antes del AGENT 1 dejan que el **N1 baje**. Con el motor más lento hay **menos ventilación en la nacelle**, y el agente extintor **funciona mejor**. El ECAM muestra la cuenta regresiva.","keyIdea":"Esperar 10 s: baja el N1, hay menos ventilación y el agente rinde más."},{"id":"fir-8-c3","title":"On the ground","body":"Con **ENG FIRE en tierra**:\n- **THR LEVERS** en **IDLE** (se puede usar la reversa máxima para detener el avión);\n- detenido el avión: **PARKING BRK ON**;\n- avisar al **ATC por VHF 1**: con solo baterías, VHF 1 es la única radio disponible;\n- alertar a la tripulación de cabina;\n- ENG MASTER en OFF, ENG FIRE pb PUSH y **AGENT 1+2**;\n- aplicar la evacuación de emergencia.","keyIdea":"En tierra: IDLE, detener, PARKING BRK, ATC por VHF 1, MASTER, FIRE pb, AGENT 1+2 y evacuación."}],"test":[{"id":"fir-8-t1","type":"mcq","question":"¿Cuál es la secuencia correcta de memory items ante un ENG 1(2) FIRE en vuelo?","options":["ENG FIRE PB push, luego Thrust Lever a IDLE, y finalmente ENG MASTER a OFF","Thrust Lever IDLE, ENG MASTER OFF, ENG FIRE PB push, AGENT 1 tras 10 s","AGENT 1 de inmediato, luego Thrust Lever IDLE","ATC primero para notificar, y luego se ejecuta el resto de las acciones memorísticas"],"correct":1,"explanation":"La secuencia memorizada es: llevar la palanca de empuje del motor afectado a IDLE, luego el ENG MASTER a OFF (cerrando las válvulas LP/HP), presionar el ENG FIRE pb (lo que arma el extintor y corta el suministro al FADEC), y solo después descargar el AGENT 1 tras una espera de 10 segundos.","taughtIn":["fir-8-c1"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:1bu4ldt"}},{"id":"fir-8-t2","type":"mcq","question":"¿Cuándo se descarga el AGENT 2 en un ENG FIRE?","options":["10 s después del AGENT 1, aunque FIRE warning haya desaparecido","30 s después del AGENT 1, aunque FIRE warning haya desaparecido","30 s después del AGENT 1, si FIRE warning persiste","60 s después del AGENT 1, si FIRE warning persiste"],"correct":2,"explanation":"AGENT 2 se descarga si el fire warning permanece 30 s después de la descarga de AGENT 1.","taughtIn":["fir-8-c1"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:i8mnsz"}},{"id":"fir-8-t3","type":"mcq","question":"Durante un ENG FIRE en tierra, una vez detenido el avión, ¿qué se hace primero respecto de los frenos?","options":["PARKING BRK...ON","PARKING BRK...OFF","AUTOBRAKE...MAX","Brake pedals only"],"correct":0,"explanation":"Una vez detenido el avión durante el ENG FIRE on ground, el memory item establece PARKING BRK ON antes de continuar la secuencia.","taughtIn":["fir-8-c3"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:j88or5"}},{"id":"fir-8-t4","type":"mcq","question":"Si tras un ENG FIRE en tierra el avión queda alimentado solo por baterías, ¿qué medio de comunicación permanece disponible?","options":["Solo VHF 1","Solo VHF 2","Solo HF 1","Solo ATC 1"],"correct":0,"explanation":"Con solo baterías, VHF 1 es la única radio disponible: por eso el ATC se avisa por VHF 1.","taughtIn":["fir-8-c3"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:1wcfqx1"}},{"id":"fir-8-t5","type":"oral","question":"Camina conmigo por la secuencia de memory items ante un ENG 1(2) FIRE en vuelo, y explica por qué es ese orden.","reference":"Primero se lleva el thrust lever del motor afectado a IDLE, luego ENG MASTER a OFF, después se presiona el ENG FIRE pushbutton para armar el extintor, y se descarga el AGENT 1 tras esperar unos 10 segundos, tiempo que permite que el N1 disminuya, reduciendo la ventilación de la góndola y así mejorando la eficacia del agente extintor.","steps":[{"concept":"Thrust lever a IDLE primero","weight":2,"required":true,"order":1,"accepted":["thrust lever idle","thrust lever a idle","palanca a idle","reducir empuje","a idle","ralenti","ralentí","palanca a ralenti"]},{"concept":"ENG MASTER OFF","weight":2,"required":true,"order":2,"accepted":["eng master off","eng master a off","apagar el motor","master off","a off"]},{"concept":"ENG FIRE pushbutton arma el extintor","weight":2,"required":true,"order":3,"accepted":["fire pushbutton","armar el extintor","fire pb","boton de fuego","pulsador de fuego","aprieto el boton"]},{"concept":"Esperar ~10s antes de AGENT 1","weight":2,"required":true,"order":4,"accepted":["10 segundos","esperar antes del agente","agent 1","diez segundos"]},{"concept":"Por qué: N1 disminuye, mejora eficacia","weight":1,"order":5,"accepted":["n1 disminuye","n1 disminuya","mas eficaz","mejor efectividad","mejora la eficacia","mejora eficacia"]}],"taughtIn":["fir-8-c1","fir-8-c2"],"source":{"bank":"oral","id":"ov_engfire"}}]},
{"id":"fir-9","subject":"fuego","order":9,"kind":"lesson","level":3,"ident":"SMF","title":"Smoke and fumes","goal":"Explicar las acciones inmediatas ante humo o vapores, cuándo desviarse y qué opciones quedan si la situación empeora.","intro":"Con humo no se espera a saber de dónde viene: primero se protege a la tripulación y se prepara la desviación.","minutes":6,"cards":[{"id":"fir-9-c1","title":"Immediate actions","body":"Si el humo o los vapores se confirman (**LAND ASAP**):\n- **máscaras de oxígeno y antiparras** si hace falta (100 %, EMERG);\n- **VENTILATION BLOWER** y **EXTRACT** en **OVRD**: el aire de la aviónica sale al exterior;\n- **CAB FANS OFF**, para que el humo no entre a la cabina de mando ni a la de pasajeros;\n- **GALY & CAB OFF** y **SIGNS ON**;\n- establecer la comunicación con la cabina.","diagram":{"alt":"El procedimiento de humo y vapores en tres partes. Inmediato: máscaras, BLOWER y EXTRACT en OVRD, CAB FANS OFF, GALY & CAB OFF, SIGNS ON y comunicación con la cabina. Si la fuente es obvia, accesible y se puede apagar: aislarla; si no se aísla de inmediato: desviación y descenso a FL 100 o MEA-MORA. En cualquier momento: si el humo es la mayor amenaza, considerar sacarlo y la ELEC EMER CONFIG; si se vuelve inmanejable, considerar un aterrizaje inmediato.","src":"assets/estaciones/diagramas/fir-humo-proc.svg"},"keyIdea":"Máscaras, BLOWER y EXTRACT en OVRD, CAB FANS OFF, GALY & CAB OFF, SIGNS ON."},{"id":"fir-9-c2","title":"Isolate or divert","body":"- Si la fuente es **obvia, accesible y se puede apagar**: aislar el equipo que falla.\n- Si la fuente **no queda aislada de inmediato**: **iniciar la desviación** y el **descenso a FL 100 o a la MEA-MORA**.\n\nLa tripulación siempre debe estar lista para desviarse de inmediato: no se espera a identificar la fuente para actuar.","keyIdea":"Fuente obvia: aislarla. Si no: desviación y descenso a FL 100 o MEA-MORA, sin esperar."},{"id":"fir-9-c3","title":"If it gets worse","body":"En **cualquier momento** del procedimiento:\n- si el humo pasa a ser la **mayor amenaza**: considerar **sacar el humo** (removal of smoke/fumes) y la **ELEC EMER CONFIG**;\n- si la situación se vuelve **inmanejable**: considerar un **aterrizaje inmediato**. Según la situación, el comandante puede considerar un aterrizaje con sobrepeso, con viento de cola, un amaraje o un aterrizaje forzoso.","keyIdea":"Mayor amenaza: sacar el humo y ELEC EMER CONFIG. Inmanejable: aterrizaje inmediato."}],"test":[{"id":"fir-9-t1","type":"mcq","question":"Ante humo/vapores confirmados en cockpit, ¿cuáles son las acciones inmediatas respecto de ventilación?","options":["Aumentar el flujo de los packs al máximo posible, sin modificar ningún control de ventilación","No modificar la ventilación de cabina hasta lograr identificar con certeza la fuente del humo","VENTILATION BLOWER y EXTRACT a OVRD, CAB FANS OFF, GALY & CAB OFF","Apagar toda la ventilación de forma indiscriminada"],"correct":2,"explanation":"Las acciones inmediatas son VENTILATION BLOWER y EXTRACT en OVRD, CAB FANS OFF y GALY & CAB OFF.","taughtIn":["fir-9-c1"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:1tvtmzw"}},{"id":"fir-9-t2","type":"mcq","question":"Si la fuente de humo no puede identificarse ni aislarse de inmediato, ¿qué dos acciones operacionales se inician?","options":["Mantener nivel y aumentar velocidad","Iniciar diversion y mantener nivel","Iniciar diversion y descenso hacia FL100 / MEA-MORA","Iniciar descenso y mantener la ruta original hasta aislar la fuente"],"correct":2,"explanation":"Cuando la fuente no es evidente ni queda aislada, el procedimiento no espera: inicia la diversión hacia el aeropuerto más adecuado y, en paralelo, un descenso hacia FL100 o el MEA/MORA correspondiente, para tener aire respirable y opciones de aterrizaje más cercanas.","taughtIn":["fir-9-c2"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:wn92a7"}},{"id":"fir-9-t3","type":"mcq","question":"En el procedimiento SMOKE/FUMES, si el humo o los vapores se convierten en la mayor amenaza, ¿qué dos acciones adicionales deben considerarse?","options":["Solo declarar la emergencia por radio","Apagar preventivamente ambos motores","Considerar REMOVAL OF SMOKE/FUMES y ELEC EMER CONFIG","Aterrizar de inmediato sin evaluar ninguna otra opción disponible"],"correct":2,"explanation":"Si el humo pasa a ser la mayor amenaza, se considera sacar el humo (removal of smoke/fumes) y la ELEC EMER CONFIG.","taughtIn":["fir-9-c3"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:23ox9u"}},{"id":"fir-9-t4","type":"mcq","question":"Si la situación de humo se vuelve «unmanageable» (inmanejable), ¿qué flexibilidad hay para el aterrizaje?","options":["Desviar al nearest suitable respetando las limitaciones normales de aterrizaje","Regresar al aeropuerto de origen si permanece dentro del alcance previsto","Considerar aterrizaje inmediato: overweight, tailwind, ditching o forced landing","Continuar hacia destino mientras la visibilidad y los sistemas sigan disponibles"],"correct":2,"explanation":"Si la situación se vuelve inmanejable, se considera un aterrizaje inmediato: según el caso, el comandante puede considerar un aterrizaje con sobrepeso, con viento de cola, un amaraje o un aterrizaje forzoso.","taughtIn":["fir-9-c3"],"source":{"bank":"fcom","system":"procedures","appId":"procedures:1mv3w4i"}},{"id":"fir-9-t5","type":"oral","question":"Si detectas humo o vapores en cockpit y no puedes identificar la fuente de inmediato, explica qué harías y por qué no conviene esperar a diagnosticar antes de actuar.","reference":"Iniciaría una diversión y un descenso hacia FL100 o el MEA/MORA aplicable de inmediato, sin esperar a identificar primero la fuente, porque el tiempo es crítico y no conviene demorar la acción para controlar el origen; conviene estar ya actuando sobre el escenario más exigente mientras en paralelo se sigue intentando identificar y aislar el humo.","concepts":[{"label":"Iniciar diversión de inmediato","weight":2,"accepted":["diversion","desviar","aeropuerto mas cercano","alterno","aeropuerto alterno"]},{"label":"Descenso hacia FL100/MEA-MORA","weight":2,"accepted":["descenso","fl100","mea","mora"]},{"label":"No esperar a diagnosticar antes de actuar","weight":2,"required":true,"accepted":["sin esperar","no esperar a identificar","actuar de inmediato","antes de saber la causa","sin saber la fuente","independiente de la causa","no importa la causa","sin importar la fuente"]},{"label":"Seguir identificando en paralelo","weight":1,"accepted":["identificar la fuente","aislar el humo","en paralelo","al mismo tiempo","mientras tanto","se sigue buscando"]}],"taughtIn":["fir-9-c2"],"source":{"bank":"oral","id":"ov_smoke"}}]},
{"id":"fir-repaso","subject":"fuego","order":10,"kind":"review","level":3,"ident":"RFI","title":"Fire protection review","goal":"Repasar la protección contra fuego: detección, extinción, tests y procedimientos.","intro":"Llegamos al repaso: preguntas de todas las estaciones de fuego, incluidas algunas nuevas.","minutes":6,"cards":[{"id":"fir-repaso-c1","title":"Fire protection in one page","body":"- **Detección:** dos loops en paralelo y una FDU en cada motor y en el APU; warning con los dos loops, con uno y el otro fallado, o con dos cortes en 5 s.\n- **Motores:** dos botellas; el ENG FIRE pb aísla el motor y arma los squibs; luz roja mientras haya fire warning.\n- **APU:** una botella; en tierra, apagado y descarga automática a los 3 s, con luz APU FIRE y bocina afuera; en vuelo, manual.\n- **Humo:** detectores en la extracción de aviónica y de lavatorios; en las bodegas, detectores con dos loops y descarga con el DISCH pb.","keyIdea":"Dos loops, dos botellas por motor, una del APU automática en tierra, humo con descarga manual en las bodegas."},{"id":"fir-repaso-c2","title":"Procedures in one page","body":"- **ENG FIRE en vuelo:** THR IDLE, MASTER OFF, FIRE pb, AGENT 1 a los 10 s, ATC, AGENT 2 a los 30 s si sigue; LAND ASAP.\n- **ENG FIRE en tierra:** detener, PARKING BRK, ATC por VHF 1, MASTER, FIRE pb, AGENT 1+2 y evacuación.\n- **Humo:** máscaras, BLOWER y EXTRACT en OVRD, CAB FANS OFF; si no se aísla, desviación y descenso a FL 100 o MEA-MORA.","keyIdea":"ENG FIRE con su orden y sus tiempos; humo con desviación sin esperar."}],"test":[{"id":"fir-repaso-t1","type":"mcq","question":"IF A BREAK IN BOTH ENGINE FIRE LOOPS OCCURS WITHIN __________ SECONDS OF EACH OTHER A __________ WILL OCCUR.","options":["10 SEC. A FIRE WARNING.","5 SEC. A FIRE DET FAULT MESSAGE ON ECAM.","5 SEC. A FIRE WARNING."],"correct":2,"explanation":"Si ambos loops de detección de un motor se interrumpen dentro de una ventana de 5 segundos entre sí, el sistema interpreta esa coincidencia como indicio de un fuego real y genera un FIRE WARNING; si la separación es mayor, se trata como una falla de detección (FIRE DET FAULT) y no como una alarma de fuego.","taughtIn":["fir-repaso-c1","fir-2-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:yzbzod"}},{"id":"fir-repaso-t2","type":"mcq","question":"HOW MANY HALON FIRE EXTINGUISHING CYLINDERS ARE PER ENGINE?","options":["EACH ENGINE HAS TWO FIRE EXTINGUISHERS.","EACH ENGINE HAS IT\\'S OWN DEDICATED FIRE EXTINGUISHER AND HAS THE CAPABILITY TO SHARE THE OTHER ENGINE\\'S CYLINDER.","EACH ENGINE HAS IT'S OWN DEDICATED FIRE EXTINGUISHER AND HAS THE CAPABILITY TO SHARE ONE CENTRALLY LOCATED HALON CYLINDER.","EACH ENGINE HAS ONE FIRE EXTINGUISHER."],"correct":0,"explanation":"Cada motor del A320 tiene dos botellas extintoras de Halón propias y dedicadas (dos disparos disponibles), sin compartir cilindros con el otro motor.","taughtIn":["fir-repaso-c1","fir-4-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1wmp8j1"}},{"id":"fir-repaso-t3","type":"mcq","question":"HOW MANY FIRE EXTINGUISHING BOTTLES ARE AVAILABLE FOR FIGHTING AN APU FIRE?","options":["ONE.","TWO.","ONE CYLINDER SHARED WITH THE AFT CARGO COMPARTMENT.","TWO CYLINDERS SHARED WITH THE AFT CARGO COMPARTMENT."],"correct":0,"explanation":"El APU cuenta con una sola botella extintora dedicada (un único disparo disponible), a diferencia de cada motor, que dispone de dos botellas propias.","taughtIn":["fir-repaso-c1","fir-5-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:vim8o3"}},{"id":"fir-repaso-t4","type":"mcq","question":"IF AN APU FIRE IS DETECTED ON THE GROUND, THE APU SHUTS DOWN AUTOMATICALLY AND THE AGENT IS DISCHARGED _____ AFTER THE WARNING IS ACTIVATED.","options":["IMMEDIATELY.","1 SECONDS.","3 SECONDS.","6 SECONDS."],"correct":2,"explanation":"En tierra, ante un fuego de APU confirmado, el sistema apaga el APU automáticamente y descarga el agente extintor 3 segundos después de activarse la alerta, sin requerir acción de la tripulación.","taughtIn":["fir-repaso-c1","fir-5-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:v7xi4n"}},{"id":"fir-repaso-t5","type":"mcq","question":"IF AN ENGINE FIRE IS DETECTED, WHEN WILL THE GUARDED RED ENG FIRE PUSH BUTTON LIGHT EXTINGUISH?","options":["ONLY AFTER THE FIRE WARNING NO LONGER EXISTS.","WHEN THE CREW PUSHES AND RELEASES THE GUARDED RED ENGINE FIRE PUSHBUTTON.","WHEN THE CREW PUSHES THE RED MASTER WARN PUSHBUTTON.","WHEN THE CREW PUSHES THE RED MASTER WARN PUSHBUTTON AND THEN RELEASES THE GUARDED ENGINE FIRE PUSHBUTTON."],"correct":0,"explanation":"La luz del pushbutton de fuego de motor solo se apaga cuando la condición de fuego deja de estar presente; ni soltar el pushbutton ni presionar MASTER WARN eliminan por sí solos la indicación mientras el fuego siga siendo detectado.","taughtIn":["fir-repaso-c1","fir-4-c3"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:134sgno"}},{"id":"fir-repaso-t6","type":"mcq","question":"ARE THERE ANY WARNINGS TO ALERT GROUND PERSONNEL WHEN THERE IS A FIRE IN THE APU COMPARTMENT?","options":["YES, BUT ONLY IF PREVIOUSLY SELECTED TO AUTOMATIC BY THE GROUND PERSONNEL.","NO, APU FIRE INDICATIONS ARE ONLY PRESENT IN THE COCKPIT.","YES, THE FLAMES.","YES, THE EXTERNAL FIRE WARNING HORN WILL SOUND AND THE APU RED FIRE LIGHT WILL ILLUMINATE."],"correct":3,"explanation":"Sí: además de las indicaciones en cabina, existe una bocina de aviso externa que suena y una luz roja de fuego visible desde el exterior, para alertar al personal de tierra sin depender de que alguien esté observando el compartimento.","taughtIn":["fir-repaso-c1","fir-5-c1"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:1qn5rs8"}},{"id":"fir-repaso-t7","type":"mcq","question":"THE APU PROVIDES FOR AUTOMATIC FIRE EXTINGUISHING:","options":["ON THE GROUND ONLY.","ON THE GROUND AND IN FLIGHT.","ONLY WHEN SELECTED TO AUTOMATIC BY GROUND PERSONNEL."],"correct":0,"explanation":"La extinción automática de fuego del APU está disponible únicamente en tierra; en vuelo, la protección exige acción manual de la tripulación, como se describe en la lógica de fuego de APU en vuelo.","taughtIn":["fir-repaso-c1","fir-5-c2"],"source":{"bank":"dgac","system":"dgac_bank","appId":"dgac_bank:17xy2c2"}}]}
]};
